/**
 * Typed access to the evaluation data.
 *
 * data/results.json is generated by `npm run sync:results` from artifacts/*.json
 * and is COMMITTED — it is the build's only data input (Vercel's root-directory
 * sandbox cannot reach ../artifacts). Import it, don't fetch it.
 */
import raw from "@/data/results.json";

export interface Curve2 {
  readonly [k: string]: readonly number[];
}

export interface ModelResult {
  auroc: number;
  aurocCi: number[];
  auprc: number;
  auprcCi: number[];
  brier: number;
  ece: number;
  prevalence: number;
  utility: number;
  /** Per level: the sensitivity reached, the specificity actually achieved
   *  (the requested level is a target, not a guarantee), and the threshold. */
  sensAtSpec: Record<
    "0.85" | "0.90" | "0.95",
    { sensitivity: number; achieved: number; threshold: number }
  >;
  earlyWarning: {
    detectionRate: number;
    medianLeadHours: number;
    meanLeadHours: number;
    falseAlarmRate: number;
    septicPatients: number;
    nonsepticPatients: number;
  };
  roc: { fpr: number[]; tpr: number[] };
  pr: { recall: number[]; precision: number[] };
  reliability: { meanPred: number[]; obsFreq: number[]; count: number[] };
  decisionCurve: {
    thresholds: number[];
    model: number[];
    treatAll: number[];
    treatNone: number[];
  };
  alarmBurden: {
    thresholds: number[];
    detectionRate: number[];
    falseAlarmRate: number[];
    falseAlertsPer100h: number[];
  };
}

export interface Direction {
  train: string;
  test: string;
  models: { gbm: ModelResult; stacked: ModelResult };
}

/** One candidate ensemble under the frontier benchmark's shared folds. */
export interface FrontierCandidate {
  auroc: number;
  aurocSd: number;
  auprc: number;
  falseAlarm: number;
  detectAtFar15: number;
}

export interface FrontierComparison {
  deltaAuroc: number;
  ci: number[];
  significant: boolean;
  /** Spearman correlation of the pooled out-of-fold scores against the incumbent.
   *  Near 1 means the candidate is a rewording of the incumbent, whatever its
   *  headline number says — which is the whole finding of this section. */
  rankCorr: number;
  detectionAtBudget?: Record<
    string,
    { delta: number; ci: number[]; significant: boolean }
  >;
}

export interface Frontier {
  protocol: string;
  rows: number;
  patients: number;
  folds: number;
  bootstrap: number;
  baseline: string;
  production: string;
  /** False until someone runs frontier_external.py. The page must say so. */
  crossHospitalConfirmed: boolean;
  candidates: Record<string, FrontierCandidate>;
  comparisons: Record<string, FrontierComparison>;
  promotion: {
    created?: string;
    gates?: Record<string, boolean>;
    promoted?: boolean;
    holdoutAurocDelta?: number;
    holdoutAuprcDelta?: number;
  };
}

export interface SubgroupCell {
  name: string; kind: string; patients: number; septic: number;
  auroc: number; aurocCi: [number, number];
  calibration: number; detection: number;
  falseAlarm: number; falseAlarmCi: [number, number];
  leadHours: number; underpowered: boolean;
}

export interface SubgroupGap {
  metric: string; a: string; b: string;
  delta: number; ci: [number, number];
}

export interface ScaleLevel {
  beds: number; p50: number; p99: number; spreadPct: number | null;
  msPerBed: number; peakRssMb: number; repeats: number;
  topPhase: string; topPhaseShare: number;
}

export type Results = typeof raw & {
  directions: { AtoB: Direction; BtoA: Direction };
  /** Null on a checkout whose artifacts predate the frontier work, so every
   *  consumer has to guard rather than assume. */
  frontier: Frontier | null;
};

export const results = raw as unknown as Results;

/* ── convenience accessors, so pages never index into raw JSON ────────────── */

export const meta = results.meta;
export const headline = results.headline;
export const generalization = results.generalization;
export const calibration = results.calibration;
export const operatingPoint = results.operatingPoint;
export const alarmPolicy = results.alarmPolicy;
export const selfImprove = results.selfImprove;
export const qhdc = results.qhdc;
export const phase7 = results.phase7;
/** The accuracy-frontier push. WITHIN-SITE cross-validation — not the
 *  cross-hospital protocol the headline uses. Null until the summary artifact has
 *  been generated, so every consumer must guard on it. */
export const frontier = results.frontier;

export const directions = results.directions;

/** Per-subgroup behaviour of the SHIPPED detector at the DEPLOYED threshold.
 *  ``significant`` holds only the gaps that survived Bonferroni over the
 *  pre-specified family; ``exploratory`` holds the worst cell, whose comparison
 *  was chosen after seeing the results and therefore claims nothing. */
export const subgroup = results.subgroup as unknown as {
  threshold: number; thresholdPolicy: string; patients: number;
  familySize: number; alphaAdjusted: number; worstCell: string;
  cells: SubgroupCell[]; significant: SubgroupGap[]; exploratory: SubgroupGap[];
};

/** Measured runtime capacity. Real tick loop, real patients, median of repeated
 *  runs — ``spreadPct`` is how much the level moved between runs, so a reader can
 *  tell whether a difference between rows is bigger than the noise inside one. */
export const scale = results.scale as unknown as {
  host: { machine: string; python: string; cpu_count: number };
  note: string; tickBudgetMs: number; levels: ScaleLevel[];
};

/** The largest ward whose p99 tick still fits the real-time budget. */
export function scaleCeiling(): ScaleLevel | null {
  const ok = scale.levels.filter((l) => l.p99 <= scale.tickBudgetMs);
  return ok.length ? ok[ok.length - 1] : null;
}

/** The four (direction × model) cells, in the order the tables read them. */
export const cells = [
  { key: "AtoB-stacked", dir: directions.AtoB, model: directions.AtoB.models.stacked, name: "stacked", production: true },
  { key: "AtoB-gbm", dir: directions.AtoB, model: directions.AtoB.models.gbm, name: "gbm", production: false },
  { key: "BtoA-stacked", dir: directions.BtoA, model: directions.BtoA.models.stacked, name: "stacked", production: true },
  { key: "BtoA-gbm", dir: directions.BtoA, model: directions.BtoA.models.gbm, name: "gbm", production: false },
] as const;

/** Short label for a direction, e.g. "BIDMC → Emory". */
export function dirLabel(d: Direction): string {
  const strip = (s: string) => s.replace(/\s*\(set [AB]\)\s*/i, "").trim();
  return `${strip(d.train)} → ${strip(d.test)}`;
}


/** ── 2026-08 additions ─────────────────────────────────────────────────────
 *  The conformal abstention layer, the label-free transfer investigation, the
 *  HDC usage record, and the architectures that were built and then refused.
 *  All four came out of one pass and three of the four are negatives. */

export interface ConformalResults {
  alpha: number; nominal: number; detector: string;
  lockedCovPos: number; lockedCovNeg: number; lockedMacroPos: number;
  abstainRate: number; miscoverageRatio: number; overrunLimit: number;
  conversion: { policy: string; utility: number; detection: number; falseAlarm: number; leadHours: number }[];
  external: { withinCovPos: number; acrossCovPos: number; delta: number; corrected: boolean; supersedes: string };
}
export const conformal = results.conformal as unknown as ConformalResults;

export interface TransferDirection {
  direction: string; domainAuc: number; priorRatioTrue: number; priorRatioEm: number;
  unadapted: number; priorCorrected: number; rateMatched: number; oracle: number;
  reachableGap: number; priorDelta: number; priorCi: number[]; priorSignificant: boolean;
}
export const transfer = results.transfer as unknown as {
  limitPerSite: number;
  directions: TransferDirection[];
  coverage: { detector: string; direction: string; plain: number; weighted: number; oracle: number }[];
};

export const hdc = results.hdc as unknown as {
  inProductionDetector: boolean;
  shippedRoster: string[];
  ablation: { name: string; auroc: number; aurocSd: number; utility: number }[];
  runtime: { beds: number; phases: { phase: string; share: number; msPerTick: number }[] };
};

export const negatives = results.negatives as unknown as {
  protocol: string;
  rows: { name: string; auroc: number; aurocSd: number; auprc: number; utility: number;
          detectAtFar15: number; seconds: number; verdict: string }[];
  minirocket: { delta: number; ci: number[]; significant: boolean; standardBankGb: number;
                shippedFeatures: number; shippedGb: number; checks: number; mutationAudited: number };
  forestVsa: { losslessCeiling: number; donorSameFold: number };
};
